//
// Argon2id password hashing with deterministic parameter encoding.
// Replaces the weak bcrypt stub Phase 1 emitted. Parameters follow
// OWASP 2023 recommendations: t=3, m=64*1024 KiB, p=4, 32-byte hash,
// 16-byte salt.
//
// Hash format (encoded for storage in a TEXT column):
//
//	$argon2id$v=19$m=65536,t=3,p=4$<base64-salt>$<base64-hash>
//
// The encoded form carries its own parameters so future cost upgrades
// stay backward-compatible — Verify reads m/t/p from the stored hash.
package auth

import (
	"crypto/rand"
	"crypto/subtle"
	"encoding/base64"
	"errors"
	"fmt"
	"strings"

	"golang.org/x/crypto/argon2"
)

// ErrPasswordMismatch is returned when verification fails. Callers
// SHOULD NOT distinguish this from "user not found" to a client — both
// must return the same 401 to defeat user-enumeration probes.
var ErrPasswordMismatch = errors.New("password mismatch")

// Default parameter set. Reviewed against OWASP cheat-sheet 2023.
const (
	defaultTime    uint32 = 3
	defaultMemory  uint32 = 64 * 1024 // KiB → 64 MiB working set
	defaultThreads uint8  = 4
	defaultKeyLen  uint32 = 32
	defaultSaltLen uint32 = 16
)

// HashPassword returns the canonical argon2id encoding of the password.
// 32-byte salt entropy from crypto/rand — fail-fast if the OS RNG is
// unavailable (the only realistic cause is a misconfigured chroot).
func HashPassword(password string) (string, error) {
	if password == "" {
		return "", errors.New("password is empty")
	}
	salt := make([]byte, defaultSaltLen)
	if _, err := rand.Read(salt); err != nil {
		return "", fmt.Errorf("password: read salt: %w", err)
	}
	hash := argon2.IDKey(
		[]byte(password),
		salt,
		defaultTime,
		defaultMemory,
		defaultThreads,
		defaultKeyLen,
	)
	return fmt.Sprintf(
		"$argon2id$v=%d$m=%d,t=%d,p=%d$%s$%s",
		argon2.Version,
		defaultMemory,
		defaultTime,
		defaultThreads,
		base64.RawStdEncoding.EncodeToString(salt),
		base64.RawStdEncoding.EncodeToString(hash),
	), nil
}

// VerifyPassword constant-time compares a candidate password against
// the stored argon2id hash. Reads cost parameters from the hash so the
// verification math matches whatever the encoder produced — supports
// rolling cost upgrades without a schema migration.
func VerifyPassword(password, stored string) error {
	if password == "" || stored == "" {
		return ErrPasswordMismatch
	}
	params, salt, want, err := decodeArgon2id(stored)
	if err != nil {
		return ErrPasswordMismatch
	}
	got := argon2.IDKey(
		[]byte(password),
		salt,
		params.t,
		params.m,
		params.p,
		uint32(len(want)),
	)
	if subtle.ConstantTimeCompare(want, got) != 1 {
		return ErrPasswordMismatch
	}
	return nil
}

// NeedsRehash returns true when the stored hash was made with weaker
// parameters than the current defaults. Callers should re-hash on the
// next successful login to roll the engagement's hashes forward.
func NeedsRehash(stored string) bool {
	p, _, _, err := decodeArgon2id(stored)
	if err != nil {
		return true
	}
	return p.t < defaultTime || p.m < defaultMemory || p.p < defaultThreads
}

// ── internals ────────────────────────────────────────────────────────

type argon2Params struct {
	t uint32
	m uint32
	p uint8
}

func decodeArgon2id(s string) (argon2Params, []byte, []byte, error) {
	parts := strings.Split(s, "$")
	if len(parts) != 6 || parts[1] != "argon2id" {
		return argon2Params{}, nil, nil, errors.New("not an argon2id hash")
	}
	var version int
	if _, err := fmt.Sscanf(parts[2], "v=%d", &version); err != nil || version != argon2.Version {
		return argon2Params{}, nil, nil, errors.New("argon2 version mismatch")
	}
	var p argon2Params
	if _, err := fmt.Sscanf(parts[3], "m=%d,t=%d,p=%d", &p.m, &p.t, &p.p); err != nil {
		return argon2Params{}, nil, nil, fmt.Errorf("argon2 params: %w", err)
	}
	salt, err := base64.RawStdEncoding.DecodeString(parts[4])
	if err != nil {
		return argon2Params{}, nil, nil, fmt.Errorf("argon2 salt: %w", err)
	}
	hash, err := base64.RawStdEncoding.DecodeString(parts[5])
	if err != nil {
		return argon2Params{}, nil, nil, fmt.Errorf("argon2 hash: %w", err)
	}
	return p, salt, hash, nil
}
